pub fn rosie_approved_bundled_markdown(rel_path: &str) -> Option<&'static str> {
    ROSIE_APPROVED_BUNDLED_MARKDOWN
        .iter()
        .find(|(path, _)| *path == rel_path)
        .map(|(_, markdown)| *markdown)
}
